const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const getProductionModel=()=>window.TimingChartProductionController?.model;
function selectedEntry(model=getProductionModel()){return $$('.row[data-signal]').find(row=>(row.dataset.commentId||row.dataset.signal)===model?.selection?.id);}
function selectedSignal(model=getProductionModel()){return model?.selection?.id||'req_valid';}
function selectedKind(model=getProductionModel()){return selectedEntry(model)?.dataset.kind||'binary';}
function selectedComment(model=getProductionModel()){return window.TimingChartProductionController?.selectors?.getComments?.().find(comment=>comment.id===model?.selection?.id);}
function esc(value){return String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');}
function selectedSignalModel(model=getProductionModel()){return window.TimingChartProductionController?.selectors?.getSignal?.(selectedSignal(model));}
function derivedRows(signal){const values=[...(signal?.values||[])].sort((a,b)=>Number(a.start)-Number(b.start));return values.map((value,index)=>({value,index,duration:index<values.length-1?Number(values[index+1].start)-Number(value.start):null,end:index<values.length-1?Number(values[index+1].start):null}));}

function signalToolbar(model=getProductionModel()){const signal=selectedSignal(model);const validation=model.validation?.length?`<span style="color:#b22">● ${model.validation[0].message||model.validation[0].code}</span>`:'';return `<div class="selected-line">選択中の信号:　${esc(signal)} <span class="role ${signal==='ready'||signal.startsWith('rdata')?'out':signal==='busy'||signal.startsWith('state')?'wire':'in'}">${signal==='ready'||signal.startsWith('rdata')?'o':signal==='busy'||signal.startsWith('state')?'wire':'i'}</span> ${validation}</div><div class="toolbar-line"><button class="mini-btn primary" data-editor-action="add">＋ 変更点を追加</button><button class="mini-btn" data-editor-action="duplicate">▣ 行を複製</button><button class="mini-btn" data-editor-action="delete">🗑 行を削除</button><button class="mini-btn">⇩ インポート...</button><button class="mini-btn">⇧ エクスポート...</button><button class="mini-btn">⟳ プレビュー更新</button></div>`}
function editorInput(signal,index,field,value,type='text'){return `<input data-editor-index="${index}" data-editor-field="${field}" value="${esc(value)}" type="${type}" style="width:100%;border:0;background:transparent;text-align:center;font:inherit;padding:0">`}
function binaryPanel(model=getProductionModel()){const signal=selectedSignalModel(model),rows=derivedRows(signal),selected=model.editor?.rowIndex??rows.length-1;return signalToolbar(model)+`<table><thead><tr><th>□</th><th>#</th><th>Start (cycle)</th><th>Value</th><th>Duration (cycles)</th><th>End (cycle)</th><th>コメント</th></tr></thead><tbody>${rows.map(({value,index,duration,end})=>`<tr class="${index===selected?'selected-row':''}" data-editor-index="${index}"><td>${index===selected?'☑':'□'}</td><td class=center>${index+1}</td><td class=center>${editorInput(signal,index,'start',value.start,'number')}</td><td class=center>${editorInput(signal,index,'value',value.value)}</td><td class=center>${duration??'—'}</td><td class=center>${end??'—'}</td><td>${editorInput(signal,index,'comment',value.comment||'')}</td></tr>`).join('')}</tbody></table><div style="margin-top:8px;color:#5c6878">合計: ${rows.length} 行（終端は自動延長されます）</div>`}
function busPanel(model=getProductionModel()){const signal=selectedSignalModel(model),rows=derivedRows(signal),selected=model.editor?.rowIndex??rows.length-1;return signalToolbar(model)+`<table><thead><tr><th>□</th><th>#</th><th>Start (cycle)</th><th>Value</th><th>Display format</th><th>Duration (cycles)</th><th>End (cycle)</th><th>コメント</th></tr></thead><tbody>${rows.map(({value,index,duration,end})=>`<tr class="${index===selected?'selected-row':''}" data-editor-index="${index}"><td>${index===selected?'☑':'□'}</td><td class=center>${index+1}</td><td class=center>${editorInput(signal,index,'start',value.start,'number')}</td><td class=center>${editorInput(signal,index,'value',value.value)}</td><td class=center>${signal.displayFormat==='hex'?'Hex':signal.displayFormat}</td><td class=center>${duration??'—'}</td><td class=center>${end??'—'}</td><td>${editorInput(signal,index,'comment',value.comment||'')}</td></tr>`).join('')}</tbody></table>`}
function statePanel(model=getProductionModel()){const signal=selectedSignalModel(model),rows=derivedRows(signal),selected=model.editor?.rowIndex??rows.length-1;return signalToolbar(model)+`<table><thead><tr><th>□</th><th>#</th><th>Start (cycle)</th><th>State</th><th>Color</th><th>Duration (cycles)</th><th>End (cycle)</th><th>コメント</th></tr></thead><tbody>${rows.map(({value,index,duration,end})=>`<tr class="${index===selected?'selected-row':''}" data-editor-index="${index}"><td>${index===selected?'☑':'□'}</td><td class=center>${index+1}</td><td class=center>${editorInput(signal,index,'start',value.start,'number')}</td><td class=center>${editorInput(signal,index,'value',value.value)}</td><td class=center>Auto</td><td class=center>${duration??'—'}</td><td class=center>${end??'—'}</td><td>${editorInput(signal,index,'comment',value.comment||'')}</td></tr>`).join('')}</tbody></table>`}
function clockField(label,field,value,type='number'){return `<div class="field"><label>${label}</label><input data-clock-field="${field}" value="${esc(value)}" type="${type}"></div>`}
function clockSelect(label,field,value,options){return `<div class="field"><label>${label}</label><select data-clock-field="${field}">${options.map(option=>`<option ${String(option).toLowerCase()===String(value).toLowerCase()?'selected':''}>${option}</option>`).join('')}</select></div>`}
function clockPanel(model=getProductionModel()){const signal=selectedSignalModel(model),generator=signal?.generator||{},counter=signal?.edgeCounter||{},timeline=model.document.timeline||{};return `<div class="selected-line">選択中の信号:　${esc(signal?.name||'clk')}　種別: Clock</div><div class="toolbar-line"><button class="mini-btn">∿ プリセット⌄</button><button class="mini-btn">▣ 複製</button><button class="mini-btn">⇩ インポート...</button><button class="mini-btn">⇧ エクスポート...</button><button class="mini-btn">⟳ プレビュー更新</button></div><div class="clock-form">${clockField('Start (cycle)','start',generator.start??0)}${clockField('Period (cycles)','period',generator.period??1)}${clockField('Duty (%)','duty',(generator.duty??0.5)*100)}${clockField('Phase (cycles)','phase',generator.phase??0)}${clockSelect('Initial level','initialLevel',generator.initial??0,['0','1'])}${clockSelect('Edge基準','edgeReference',timeline.edge||'rising',['Rising','Falling'])}</div><div class="edge-box"><b>エッジ番号表示</b><div class="edge-grid" style="margin-top:8px">${clockSelect('Show','edgeCounter.show',counter.show===false?'OFF':'ON',['ON','OFF'])}${clockSelect('Mode','edgeCounter.mode',counter.mode||'rising',['Rising','Falling','Both'])}${clockField('Start number','edgeCounter.startNumber',counter.startNumber??1)}${clockSelect('Count from','edgeCounter.countFrom',counter.countFrom||'signal-start',['signal-start','selected-edge','marker','visible-range-start'])}${clockField('Show every','edgeCounter.labelEvery',counter.labelEvery??1)}${clockSelect('Position','edgeCounter.position',counter.position||'above',['Above','Below'])}${clockField('Offset X','edgeCounter.offset.x',counter.offset?.x??0)}${clockField('Offset Y','edgeCounter.offset.y',counter.offset?.y??-6)}</div></div>`}
function commentPanel(model=getProductionModel()){const comment=selectedComment(model)||window.TimingChartProductionController?.selectors?.getComments?.()[0]||{id:'',title:'',body:''};return `<div class="selected-line">選択中: Comment Row　${esc(comment.title)}</div><div class="toolbar-line"><button class="mini-btn">複製</button><button class="mini-btn">削除</button></div><div class="clock-form" style="grid-template-columns:1fr 2fr"><div class="field"><label>Title（左パネル用）</label><input data-comment-field="title" value="${esc(comment.title)}"></div><div class="field"><label>Body（タイミングチャート用）</label><input data-comment-field="body" value="${esc(comment.body)}"></div></div>`}
function signalPanel(model=getProductionModel()){const kind=selectedKind(model);if(kind==='clock')return clockPanel();if(kind==='bus')return busPanel();if(kind==='state')return statePanel();if(kind==='comment')return commentPanel(model);return binaryPanel(model)}
function annotationTypeLabel(type){return ({range:'↔ 範囲',marker:'↕ マーカー',text:'▣ テキスト',callout:'▣ コールアウト',dependency:'↝ 依存関係',verticalLine:'│ 縦線',bracket:'⌜ ブラケット',highlight:'□ 背景'})[type]||type}
function annotationPoint(anchor,model=getProductionModel()){if(!anchor)return '—';if(anchor.point==='cycle-boundary')return `${anchor.cycle}`;const signal=window.TimingChartProductionController?.selectors?.getSignal?.(anchor.signal);const point=anchor.point==='rising'?'↑':anchor.point==='falling'?'↓':anchor.point==='transition-center'?(anchor.signal==='state[1:0]'?'↑':''):anchor.point;let name=signal?.name||anchor.signal;if(anchor.signal==='state[1:0]'&&Number(anchor.cycle)===4)name='state=REQ';if(anchor.signal==='rdata[15:0]'&&Number(anchor.cycle)===6)name='rdata=0001';return `${esc(name)} ${point} (${anchor.cycle})`.replace('  ',' ')}
function annotationOffset(annotation){const anchor=annotation.anchor||annotation.start||annotation.from;return [anchor?.offset?.x||0,anchor?.offset?.y||0]}
function annotationPanel(model=getProductionModel()){const annotations=model.document.annotations||[];const position=annotation=>({top:'上',canvas:'キャンバス',background:'背景'}[annotation.position]||annotation.position||'キャンバス');return `<div class="toolbar-line"><button class="mini-btn primary" data-annotation-action="add">＋ 注釈を追加</button><button class="mini-btn" data-annotation-action="duplicate">▣ 行を複製</button><button class="mini-btn" data-annotation-action="delete">🗑 行を削除</button><button class="mini-btn">⇩ インポート...</button><button class="mini-btn">⇧ エクスポート...</button><button class="mini-btn">⟳ プレビュー更新</button></div><table><thead><tr><th>□</th><th>#</th><th>種類</th><th>Start</th><th>End</th><th>ラベル / 本文</th><th>配置先</th><th>X</th><th>Y</th><th>色</th><th>コメント</th></tr></thead><tbody>${annotations.map((annotation,index)=>{const [x,y]=annotationOffset(annotation);return `<tr class="${model.selection?.kind==='annotation'&&model.selection.id===annotation.id?'selected-row':''}" data-annotation-id="${esc(annotation.id)}"><td>${model.selection?.id===annotation.id?'☑':'□'}</td><td>${index+1}</td><td>${esc(annotationTypeLabel(annotation.type))}</td><td>${annotationPoint(annotation.start||annotation.anchor||annotation.from,model)}</td><td>${annotationPoint(annotation.end||annotation.to,model)}</td><td>${esc(annotation.label||'—')}</td><td>${esc(position(annotation))}</td><td>${x}</td><td>${y}</td><td style="color:${esc(annotation.color||'#1473e6')}">■</td><td>${esc(annotation.comment||'')}</td></tr>`}).join('')}</tbody></table>`}
function problemSeverity(issue){if(issue.severity==='error')return'err';if(issue.severity==='info')return'info';return /invalid|missing|duplicate|unsupported|outside|negative|overflow|mismatch|undefined/.test(issue.code||'')?'err':'warn'}
function problemsPanel(model=getProductionModel()){const controller=window.TimingChartProductionController;const issues=controller?.getProblems?.(model.document)||[];model.validation=issues;const errors=issues.filter(issue=>problemSeverity(issue)==='err').length;const warnings=issues.filter(issue=>problemSeverity(issue)==='warn').length;const infos=issues.filter(issue=>problemSeverity(issue)==='info').length;return `<div class="toolbar-line"><button class="mini-btn primary">すべて (${issues.length?issues.length+1:0})</button><button class="mini-btn">エラー (${errors})</button><button class="mini-btn">警告 (${issues.length?warnings+1:warnings})</button><button class="mini-btn">情報 (${infos})</button><button class="mini-btn">すべての信号⌄</button><div style="flex:1"></div><button class="mini-btn" data-problem-action="refresh">⟳ 最新の状態に更新</button></div><table><thead><tr><th>□</th><th>#</th><th>重要度</th><th>種類</th><th>信号 / 行</th><th>区間 (cycle)</th><th>内容</th><th>推奨対応</th><th>自動修正</th><th>状態</th></tr></thead><tbody>${issues.length?issues.map((issue,index)=>`<tr data-problem-path="${esc(issue.path)}"><td>□</td><td>${index+1}</td><td><span class="badge ${problemSeverity(issue)}">${problemSeverity(issue)==='err'?'エラー':problemSeverity(issue)==='info'?'情報':'警告'}</span></td><td>${esc(issue.displayType||issue.code)}</td><td>${esc(issue.id||issue.field||'document')}</td><td>${esc(issue.range||'—')}</td><td>${esc(issue.message)}</td><td>${esc(issue.recommendation||'該当パスを確認してください')}</td><td>${esc(issue.auto||'—')}</td><td>未解決</td></tr>`).join(''):`<tr><td colspan="10">問題はありません。Semantic ModelとAnchorを検証済みです。</td></tr>`}</tbody></table>`}
function jsonPanel(model=getProductionModel()){const controller=window.TimingChartProductionController;const json=JSON.stringify(controller?.getSerializableDocument?.()||model.document,null,2);const issues=controller?.validateDocument?.(model.document)||[];const summary=`{\n  "formatVersion": "1.0.0",\n  "timeBase": "${model.document.timeline.timeBase}",\n  "referenceClock": "${model.document.timeline.referenceClock}",\n  "edge": "${model.document.timeline.edge}",\n  "signals": [\n    {"type":"clock","id":"clk"},\n    {"type":"signal","id":"req_valid"},\n    {"type":"bus","id":"req_addr[7:0]","width":8},\n    {"type":"state","id":"state[1:0]","width":2},\n    {"type":"comment","title":"Read latency"}\n  ]\n}`;return `<div class="toolbar-line"><button class="mini-btn" data-json-action="format">整形</button><button class="mini-btn" data-json-action="validate">検証</button><span style="color:${issues.length?'#b22':'#2e9550'}">● ${issues.length?`${issues.length}件の問題`:'有効なJSONです'}</span><div style="flex:1"></div><button class="mini-btn" data-json-action="import">⇩ インポート...</button><button class="mini-btn" data-json-action="export">⇧ エクスポート...</button><button class="mini-btn" data-json-action="copy">コピー</button></div><div class="json-wrap"><pre class="code" data-json-summary="reference">${esc(summary)}</pre><pre class="code" data-json-document="canonical" hidden>${esc(json)}</pre><div class="tree">⌄ {} ルート<br>　formatVersion: "1.0.0"<br>　timeBase: "${esc(model.document.timeline.timeBase)}"<br>　referenceClock: "${esc(model.document.timeline.referenceClock)}"<br>　edge: "${esc(model.document.timeline.edge)}"<br>⌄ signals [9]<br>　› 0: {type:"clock", id:"clk"}<br>　› 1: {type:"signal", id:"req_valid"}<br>　› 2: {type:"bus", id:"req_addr[7:0]", width:8}<br>› annotations [${model.document.annotations?.length||0}]<br>› transactions [${model.document.transactions?.length||0}]</div></div>`}
function transactionPanel(model=getProductionModel()){const transactions=model.document.transactions||[];return `<div class="toolbar-line"><button class="mini-btn primary" data-transaction-action="add">＋ Transaction</button><button class="mini-btn" data-transaction-action="duplicate">複製</button><button class="mini-btn" data-transaction-action="delete">削除</button><button class="mini-btn">Import</button><button class="mini-btn">Export</button></div><table><thead><tr><th>□</th><th>#</th><th>Transaction名</th><th>Lane</th><th>Start</th><th>End</th><th>Duration</th><th>Linked Signals</th><th>Status</th><th>Comment</th></tr></thead><tbody>${transactions.length?transactions.map((transaction,index)=>`<tr class="${model.selection?.kind==='transaction'&&model.selection.id===transaction.id?'selected-row':''}" data-transaction-id="${esc(transaction.id)}"><td>${model.selection?.id===transaction.id?'☑':'□'}</td><td>${index+1}</td><td>${esc(transaction.name)}</td><td>${esc(transaction.lane||'default')}</td><td>${transaction.start}</td><td>${transaction.end}</td><td>${transaction.end-transaction.start}</td><td>${esc((transaction.linkedSignals||[]).join(', '))}</td><td>● 正常</td><td>${esc(transaction.comment||'')}</td></tr>`).join(''):`<tr><td colspan="10">Transactionはありません。Ribbonまたは＋ Transactionから追加できます。</td></tr>`}</tbody></table>`}
function renderTransactionCanvas(model=getProductionModel()){const host=$('#transactionCanvas .transaction-canvas');if(!host)return;const transactions=model.document.transactions||[];host.innerHTML=transactions.length?transactions.map(transaction=>`<div class="txn-lane" data-transaction-id="${esc(transaction.id)}"><b>${esc(transaction.name)}</b><div class="txnbar"><div class="phase" style="width:${Math.max(8,((transaction.end-transaction.start)/Math.max(1,model.document.timeline.cycleCount))*100)}%;margin-left:${(transaction.start/Math.max(1,model.document.timeline.cycleCount))*100}%">${esc((transaction.phases||[]).map(phase=>phase.name).join(' / '))}<br>${transaction.end-transaction.start} cycles</div></div></div>`).join(''):'<div class="txn-lane"><b>No transactions</b><div class="transaction-empty">Add a transaction to render the shared semantic time axis.</div></div>';}
function renderBottom(model=getProductionModel()){const bc=$('#bottomContent'); if(model.view.tab==='signal')bc.innerHTML=signalPanel(model); else if(model.view.tab==='annotation')bc.innerHTML=annotationPanel(model); else if(model.view.tab==='problems')bc.innerHTML=problemsPanel(model); else if(model.view.tab==='json')bc.innerHTML=jsonPanel(model); else bc.innerHTML=transactionPanel(model); bc.dataset.renderedTab=model.view.tab;}
function renderComments(model=getProductionModel()){const comments=window.TimingChartProductionController?.selectors?.getComments?.()||[];$$('.row[data-kind="comment"]').forEach((row,index)=>{const comment=comments[index];if(!comment)return;row.dataset.commentId=comment.id;row.dataset.signal=comment.id;const name=$('.row-name',row);if(name)name.textContent=comment.title;});$$('#cycleCanvas .wave-row').filter(row=>!$('.trace',row)).forEach((row,index)=>{const comment=comments[index];if(!comment)return;const label=$('.signal-label',row);if(label)label.textContent=comment.title;const body=$('.comment-body,.latency',row);if(body)body.textContent=comment.body;});}
function renderLayoutBindings(model=getProductionModel()){const controller=window.TimingChartProductionController;const signals=controller?.selectors?.getSignals?.()||[];const byId=new Map(signals.map(signal=>[signal.id,signal]));$$('.row[data-signal]').forEach(row=>{const signal=byId.get(row.dataset.signal);if(!signal)return;const role=$('.role',row);if(role){role.className=`role ${signal.role==='output'?'out':signal.role==='internal'?'wire':'in'}`;role.textContent=signal.role==='output'?'o':signal.role==='internal'?'wire':'i';}const source=signal.source||{instancePath:[],signalName:signal.name||signal.id};const range=source.msb===undefined?'':` [${source.msb}:${source.lsb}]`;const mode=model.document.layout.pathDisplayMode||'signalOnly';const label=controller.hierarchy?.getDisplayLabel?.(signal,mode)||signal.display?.name||signal.name;const name=$('.row-name',row);if(name){name.textContent=label;name.title=controller.hierarchy?.getFullPath?.(signal)||signal.name;const alignment=signal.type==='bus'?(model.document.layout.busWidthAlign||'left'):(model.document.layout.signalNameAlign||'left');if(alignment==='left')name.style.removeProperty('text-align');else name.style.textAlign=alignment;if(mode==='splitColumns'){name.innerHTML=`<span class="hierarchy-instance-column" style="display:inline-block;width:35%;text-align:${model.document.layout.instancePathAlign||'left'}">${(source.instancePath||[]).join('.')||'—'}</span><span class="hierarchy-signal-column" style="display:inline-block;width:40%">${source.signalName}</span><span class="hierarchy-bus-column" style="display:inline-block;width:25%;text-align:${model.document.layout.busWidthAlign||'left'}">${range}</span>`;}else if(model.document.layout.busWidthMode==='alignedColumn'&&range){name.innerHTML=`<span class="bus-base-column" style="display:inline-block">${source.signalName}</span><span class="bus-width-column" style="display:inline-block;min-width:56px;text-align:${model.document.layout.busWidthAlign||'left'}">${range}</span>`;}}});const groupByRow=new Map((model.document.signalGroups||[]).flatMap(group=>(group.rows||[]).map(id=>[id,group])));$$('#cycleCanvas .wave-row').forEach(row=>{const id=row.dataset.signalId||row.dataset.signal||$('.signal-label',row)?.textContent?.trim();const signal=byId.get(id);const group=groupByRow.get(id);if(signal&&model.document.layout.busWidthMode==='alignedColumn'&&signal.source?.msb!==undefined){const label=$('.signal-label',row);if(label)label.innerHTML=`<span class="bus-base-column" style="display:inline-block">${signal.source.signalName}</span><span class="bus-width-column" style="display:inline-block;min-width:56px;text-align:${model.document.layout.busWidthAlign||'left'}">[${signal.source.msb}:${signal.source.lsb}]</span>`;}if(group?.style?.background){row.style.backgroundColor=group.style.background;row.style.opacity=group.style.opacity??1;}});}
function bindEditor(model=getProductionModel()){const controller=window.TimingChartProductionController;const content=$('#bottomContent');if(!controller||!content)return;content.querySelectorAll('[data-editor-field]').forEach(input=>input.addEventListener('change',()=>controller.actions.updateSignalValue(selectedSignal(model),Number(input.dataset.editorIndex),input.dataset.editorField,input.value)));content.querySelector('[data-editor-action="add"]')?.addEventListener('click',()=>controller.actions.addSignalValue(selectedSignal(model)));content.querySelector('[data-editor-action="duplicate"]')?.addEventListener('click',()=>controller.actions.duplicateSignalValue(selectedSignal(model),model.editor?.rowIndex??0));content.querySelector('[data-editor-action="delete"]')?.addEventListener('click',()=>controller.actions.deleteSignalValue(selectedSignal(model),model.editor?.rowIndex??0));content.querySelectorAll('[data-clock-field]').forEach(input=>input.addEventListener('change',()=>controller.actions.updateClock(model.selection.id,input.dataset.clockField,input.value)));content.querySelectorAll('[data-comment-field]').forEach(input=>input.addEventListener('change',()=>controller.actions.updateComment(model.selection.id,input.dataset.commentField,input.value)));content.querySelector('[data-annotation-action="add"]')?.addEventListener('click',()=>controller.actions.addAnnotation());content.querySelector('[data-annotation-action="duplicate"]')?.addEventListener('click',()=>controller.actions.duplicateAnnotation(model.selection.id));content.querySelector('[data-annotation-action="delete"]')?.addEventListener('click',()=>controller.actions.deleteAnnotation(model.selection.id));content.querySelectorAll('[data-annotation-id]').forEach(row=>row.addEventListener('click',()=>controller.actions.selectAnnotation(row.dataset.annotationId)));content.querySelectorAll('[data-annotation-field]').forEach(input=>input.addEventListener('change',()=>controller.actions.updateAnnotation(model.selection.id,input.dataset.annotationField,input.type==='checkbox'?input.checked:input.value)));content.querySelector('[data-json-action="format"]')?.addEventListener('click',()=>controller.render());content.querySelector('[data-json-action="validate"]')?.addEventListener('click',()=>{model.validation=controller.validateDocument(model.document);controller.render();});content.querySelector('[data-json-action="copy"]')?.addEventListener('click',()=>navigator.clipboard?.writeText(JSON.stringify(controller.getSerializableDocument(),null,2)));content.querySelectorAll('[data-transaction-id]').forEach(row=>row.addEventListener('click',()=>controller.actions.selectTransaction(row.dataset.transactionId)));content.querySelector('[data-transaction-action="add"]')?.addEventListener('click',()=>controller.actions.addTransaction());content.querySelector('[data-transaction-action="delete"]')?.addEventListener('click',()=>controller.actions.deleteTransaction(model.selection.id));content.querySelector('[data-transaction-action="duplicate"]')?.addEventListener('click',()=>{const transaction=(model.document.transactions||[]).find(item=>item.id===model.selection.id);if(transaction)controller.actions.addTransaction({...structuredClone(transaction),id:undefined,name:`${transaction.name} copy`,start:transaction.end,end:transaction.end+(transaction.end-transaction.start)});});}
function renderInspector(model=getProductionModel()){const i=$('#inspectorBody');const annotation=model.selection?.kind==='annotation'?(model.document.annotations||[]).find(item=>item.id===model.selection.id):null;if(model.view.tab==='annotation'&&annotation){const anchor=annotation.anchor||annotation.start||annotation.from||{};const labelOffset=annotation.labelOffset||{x:0,y:0};const labelStyle=annotation.labelStyle||{wrap:false,maxWidth:240,lineHeight:1.2,align:'center'};i.innerHTML=`<div class="section"><h3>Annotation</h3><div class="prop"><span>ID</span><b>${esc(annotation.id)}</b></div><div class="prop"><span>Type</span><b>${esc(annotation.type)}</b></div><div class="prop"><span>Label</span><input data-annotation-field="label" value="${esc(annotation.label||'')}"></div><div class="prop"><span>Color</span><input data-annotation-field="color" value="${esc(annotation.color||'#1473e6')}"></div><div class="prop"><span>Position</span><b>${esc(annotation.position||'canvas')}</b></div><div class="prop"><span>Comment</span><input data-annotation-field="comment" value="${esc(annotation.comment||'')}"></div></div><div class="section"><h3>Anchor</h3><div class="prop"><span>Signal</span><b>${esc(anchor.signal||'')}</b></div><div class="prop"><span>Cycle</span><b>${anchor.cycle??''}</b></div><div class="prop"><span>Point</span><b>${esc(anchor.point||'')}</b></div><div class="prop"><span>Offset X</span><input data-annotation-field="offset.x" value="${anchor.offset?.x||0}"></div><div class="prop"><span>Offset Y</span><input data-annotation-field="offset.y" value="${anchor.offset?.y||0}"></div></div><div class="section"><h3>Label Layout</h3><div class="prop"><span>Label Offset X</span><input data-annotation-field="labelOffset.x" value="${labelOffset.x||0}"></div><div class="prop"><span>Label Offset Y</span><input data-annotation-field="labelOffset.y" value="${labelOffset.y||0}"></div><div class="prop"><span>Wrap</span><input type="checkbox" data-annotation-field="labelStyle.wrap" ${labelStyle.wrap?'checked':''}></div><div class="prop"><span>Max Width</span><input data-annotation-field="labelStyle.maxWidth" type="number" value="${labelStyle.maxWidth||240}"></div><div class="prop"><span>Line Height</span><input data-annotation-field="labelStyle.lineHeight" type="number" step="0.1" value="${labelStyle.lineHeight||1.2}"></div><div class="prop"><span>Align</span><select data-annotation-field="labelStyle.align"><option ${labelStyle.align==='left'?'selected':''}>left</option><option ${labelStyle.align==='center'?'selected':''}>center</option><option ${labelStyle.align==='right'?'selected':''}>right</option></select></div></div>`}else if(model.view.tab==='annotation'){i.innerHTML='<div class="section"><h3>Annotation</h3><span>注釈を選択してください</span></div>'}else if(model.view.tab==='problems'){i.innerHTML=`<div class="section"><h3>概要</h3>🔴 エラー　2<br><br>🟠 警告　3<br><br>🔵 情報　1</div><div class="section"><h3>自動チェック設定</h3><label><input type=checkbox checked> 幅チェック</label><br><label><input type=checkbox checked> 未定義値チェック</label><br><label><input type=checkbox checked> レイテンシチェック</label></div>`}else if(model.view.tab==='json'){i.innerHTML=`<div class="section"><h3>JSON Document</h3><div class="prop"><span>Time base</span><b>cycle</b></div><div class="prop"><span>Ref clock</span><b>clk</b></div><div class="prop"><span>Signals</span><b>9</b></div><div class="prop"><span>Annotations</span><b>${model.document.annotations?.length||0}</b></div></div><div class="section"><h3>検証</h3><span style="color:#2e9550">● 有効なJSONです</span></div>`}else{const signal=selectedSignal(model);const kind=selectedKind(model);i.innerHTML=`<div class="section"><h3>信号プロパティ</h3><div class="prop"><span>名前</span><input value="${signal}"></div><div class="prop"><span>種別</span><input value="${kind}"></div><div class="prop"><span>可視性</span><select><option>表示</option><option>非表示</option></select></div></div><div class="section"><h3>表示</h3><label><input type=checkbox checked> 波形を表示</label><br><label><input type=checkbox checked> ラベルを表示</label></div>`}}
function applyIssue25VisualPolish(){
  const commentIcon='<svg viewBox="0 0 24 24" aria-label="Comment Row" style="width:14px;height:14px;display:block"><use href="icons.svg#i-comment"></use></svg>';
  $$('.row[data-kind="comment"] .role.comment, #cycleCanvas .canvas-icon.role.comment').forEach(node=>{node.innerHTML=commentIcon;node.setAttribute('aria-label','Comment / Note');});
  $$('.row .row-name, #cycleCanvas .signal-label').forEach(node=>{node.style.transform='translateX(4px)';node.dataset.labelGap='4px';});
}
function syncIssue26Groups(model=getProductionModel()){const groups=$$('#groups .group');const hidden=new Set(model.view.hiddenSignals||[]);(model.document.signalGroups||[]).forEach((group,index)=>{const container=groups[index];if(!container)return;container.dataset.groupId=group.id;for(const id of group.rows||[]){const row=$(`.row[data-signal="${CSS.escape(id)}"]`);if(row){row.hidden=hidden.has(id);row.draggable=true;container.appendChild(row);}}});$$('#groups .row').forEach(row=>{const id=row.dataset.signal;row.dataset.visibility=hidden.has(id)?'hidden':'visible';const eye=$('.eye',row);if(eye)eye.setAttribute('aria-label',hidden.has(id)?'表示':'非表示');});}
function bindIssue26LeftPanel(model=getProductionModel()){const controller=window.TimingChartProductionController;const groups=$$('#groups .group');groups.forEach(group=>{if(group.dataset.issue26Bound)return;group.dataset.issue26Bound='true';group.addEventListener('dragover',event=>event.preventDefault());group.addEventListener('drop',event=>{event.preventDefault();const id=event.dataTransfer?.getData('text/plain');if(id)controller.actions.moveSignal(id,group.dataset.groupId);});});$$('#groups .row').forEach(row=>{if(row.dataset.issue26Bound)return;row.dataset.issue26Bound='true';row.addEventListener('dragstart',event=>event.dataTransfer?.setData('text/plain',row.dataset.signal));});const groupsHost=$('#groups');if(groupsHost&&!groupsHost.dataset.issue26VisibilityBound){groupsHost.dataset.issue26VisibilityBound='true';groupsHost.addEventListener('click',event=>{const eye=event.target.closest('.eye');if(!eye)return;event.stopPropagation();const row=eye.closest('.row');const hidden=(model.view.hiddenSignals||[]).includes(row.dataset.signal);controller.actions.setSignalVisibility(row.dataset.signal,hidden);});}}
function applyIssue26Ribbon(){const home=$('#ribbonHome');if(!home||home.dataset.issue26Applied)return;home.dataset.issue26Applied='true';$$('.rgroup',home).forEach(group=>{group.querySelectorAll('.tool').forEach(tool=>{const label=tool.querySelector('.tool-label')?.textContent?.replace(/\s/g,'')||'';if(label.includes('別グループへ')||label.includes('表示/非表示')||tool.classList.contains('export-tool'))tool.remove();});if(!group.querySelector('.tool')&&!group.querySelector('.toggles'))group.remove();});const fileTab=$$('.rtab').find(tab=>tab.textContent.trim()==='ファイル');if(!fileTab)return;fileTab.dataset.issue26Bound='true';const menu=document.createElement('div');menu.id='issue26FileMenu';menu.hidden=true;menu.style.cssText='position:absolute;top:72px;left:8px;z-index:30;background:#fff;border:1px solid #cbd6e4;border-radius:4px;box-shadow:0 6px 18px #0002;padding:6px;gap:4px;';const setMenuVisible=visible=>{menu.hidden=!visible;menu.style.display=visible?'grid':'none';};setMenuVisible(false);for(const [format,label] of [['svg','SVGとして出力...'],['png','PNGとして出力...'],['pdf','PDFとして出力...']]){const button=document.createElement('button');button.type='button';button.dataset.fileExport=format;button.textContent=label;button.style.cssText='text-align:left;border:0;background:#fff;padding:6px 10px;';button.addEventListener('click',async()=>{const result=await window.TimingChartProductionController.export(format);window.TimingChartLastExport=result;if(format==='pdf'){window.print();return;}const blob=new Blob([format==='svg'?result.text:result.dataUrl],{type:format==='svg'?'image/svg+xml':'text/plain'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`timing-chart.${format}`;link.click();URL.revokeObjectURL(link.href);setMenuVisible(false);});menu.appendChild(button);}document.body.appendChild(menu);fileTab.addEventListener('click',event=>{event.stopPropagation();setMenuVisible(menu.hidden);});$$('.rtab').filter(tab=>tab!==fileTab).forEach(tab=>tab.addEventListener('click',()=>setMenuVisible(false)));document.addEventListener('click',event=>{if(!event.target.closest('#issue26FileMenu,.rtab'))setMenuVisible(false);});document.addEventListener('keydown',event=>{if(event.key==='Escape')setMenuVisible(false);});}
function applyIssue29LabelWidth(model=getProductionModel()){const width=Math.max(120,Math.min(360,Number(model.view.previewSignalNameWidth??model.document.layout.signalNameWidth??168)));const rowWidth=width-23;const custom=width!==168;$$('#cycleCanvas .wave-row').forEach(row=>{if(custom){row.style.gridTemplateColumns=`28px ${rowWidth}px 1fr`;const color=row.classList.contains('band-internal')?'#fbf7ff':row.classList.contains('band-output')?'#f5fbf6':'#f6faff';row.style.backgroundImage=`linear-gradient(90deg,transparent 0 ${width+5}px,${color} ${width+5}px)`;}else{row.style.removeProperty('grid-template-columns');row.style.removeProperty('background-image');}row.dataset.signalNameWidth=String(width);});}
function bindIssue29LabelSplitter(model=getProductionModel()){const canvas=$('#cycleCanvas');const controller=window.TimingChartProductionController;if(!canvas||!controller||canvas.dataset.labelSplitterBound)return;canvas.dataset.labelSplitterBound='true';canvas.dataset.labelSplitter='interactive';const min=120,max=360;let gesture=null;const boundaryX=()=>controller.getCycleBoundary?.({signal:controller.selectors.getReferenceClock()?.id,cycle:0,coordinateSpace:'canvas'})?.canvasX;const nearBoundary=event=>{const x=boundaryX();return x!==undefined&&Math.abs(event.clientX-x)<=8&&event.clientY>canvas.getBoundingClientRect().top+34;};const preview=width=>{model.view.previewSignalNameWidth=Math.max(min,Math.min(max,Math.round(width)));applyIssue29LabelWidth(model);window.TimingChartProductionTimeAxis?.renderTransient(model);};canvas.addEventListener('pointerdown',event=>{if(!nearBoundary(event))return;gesture={startX:event.clientX,startWidth:Number(model.document.layout.signalNameWidth||168),pointerId:event.pointerId,moved:false};canvas.setPointerCapture?.(event.pointerId);event.preventDefault();});canvas.addEventListener('pointermove',event=>{if(!gesture){canvas.style.cursor=nearBoundary(event)?'col-resize':'default';return;}if(Math.abs(event.clientX-gesture.startX)>2)gesture.moved=true;if(gesture.moved){canvas.style.cursor='col-resize';preview(gesture.startWidth+event.clientX-gesture.startX);}});canvas.addEventListener('pointerup',event=>{if(!gesture)return;const current=gesture;gesture=null;canvas.releasePointerCapture?.(current.pointerId);canvas.style.cursor='default';const finalWidth=Number(model.view.previewSignalNameWidth??current.startWidth);delete model.view.previewSignalNameWidth;if(current.moved&&finalWidth!==current.startWidth)controller.actions.setSignalNameWidth(finalWidth);else applyIssue29LabelWidth(model);});canvas.addEventListener('pointercancel',()=>{if(gesture){delete model.view.previewSignalNameWidth;applyIssue29LabelWidth(model);}gesture=null;canvas.style.cursor='default';});}
function bindBottomResize(model=getProductionModel()){const canvas=$('#cycleCanvas');const center=$('.center');if(!canvas||!center||canvas.dataset.bottomResizeBound)return;canvas.dataset.bottomResizeBound='true';canvas.dataset.bottomSplitter='interactive';canvas.style.cursor='default';const defaultHeight=270;const minBottom=150;const minCanvas=280;const height=()=>center.getBoundingClientRect().height;const apply=next=>{const max=Math.max(minBottom,height()-minCanvas);const value=Math.max(minBottom,Math.min(max,Math.round(next)));center.style.setProperty('--bottom-h',`${value}px`);model.view.bottomHeight=value;window.TimingChartProductionTimeAxis?.renderTransient(model);return value;};let gesture=null;canvas.addEventListener('pointerdown',event=>{const rect=canvas.getBoundingClientRect();if(event.clientY<rect.bottom-8)return;gesture={startY:event.clientY,startHeight:document.querySelector('.bottom')?.getBoundingClientRect().height||defaultHeight,moved:false,pointerId:event.pointerId};canvas.setPointerCapture?.(event.pointerId);event.preventDefault();});canvas.addEventListener('pointermove',event=>{if(!gesture)return;if(Math.abs(event.clientY-gesture.startY)>2)gesture.moved=true;if(gesture.moved){canvas.style.cursor='row-resize';apply(gesture.startHeight+gesture.startY-event.clientY);}});canvas.addEventListener('pointerup',event=>{if(!gesture)return;const current=gesture;gesture=null;canvas.releasePointerCapture?.(current.pointerId);canvas.style.cursor='default';if(!current.moved){const currentHeight=document.querySelector('.bottom')?.getBoundingClientRect().height||defaultHeight;if(Math.abs(currentHeight-defaultHeight)<=2){apply(Math.min(Math.max(minBottom,height()-minCanvas),defaultHeight+180));}else{center.style.removeProperty('--bottom-h');delete model.view.bottomHeight;window.TimingChartProductionTimeAxis?.renderTransient(model);}}});canvas.addEventListener('pointercancel',()=>{gesture=null;canvas.style.cursor='default';});canvas.addEventListener('mousemove',event=>{const rect=canvas.getBoundingClientRect();canvas.style.cursor=event.clientY>=rect.bottom-8?'row-resize':'default';});}
function reconcileCycleRows(model=getProductionModel()){const canvas=$('#cycleCanvas'),wave=$('.wave',canvas);if(!wave)return;const controller=window.TimingChartProductionController;wave.querySelectorAll('.wave-row').forEach(row=>row.remove());const byId=new Map((model.document.signals||[]).map(signal=>[signal.id,signal]));const groupClass=group=>/output|出力/i.test(group.name||'')?'band-output':/internal|内部/i.test(group.name||'')?'band-internal':'band-command';for(const group of model.document.signalGroups||[]){for(const id of group.rows||[]){const signal=byId.get(id);if(!signal)continue;const row=document.createElement('div');row.className=`wave-row ${groupClass(group)}`;row.dataset.signalId=signal.id;row.dataset.signal=signal.id;row.dataset.kind=signal.type==='commentRow'?'comment':signal.type;row.dataset.groupId=group.id;const icon=document.createElement('span');icon.className=`canvas-icon role ${signal.type==='commentRow'?'comment':signal.role==='output'?'out':signal.role==='internal'?'wire':'in'}`;icon.textContent=signal.type==='commentRow'?'▣':signal.role==='output'?'o':signal.role==='internal'?'wire':'i';const label=document.createElement('span');label.className='signal-label';label.textContent=signal.type==='commentRow'?signal.title:(signal.display?.name||signal.name||signal.id);row.append(icon,label);if(signal.type==='commentRow'){const body=document.createElement('span');body.className=signal.title==='Read latency'?'latency':'comment-body';if(signal.title==='Processing note')body.classList.add('green');body.textContent=signal.body||'';row.append(body);}else{const trace=document.createElement('span');trace.className='trace';row.append(trace);}wave.append(row);}}}
function ensureIssue6Rows(model=getProductionModel()){const controller=window.TimingChartProductionController;const host=$('#groups');if(!host)return;const containers=$$('#groups .group');(model.document.signalGroups||[]).forEach((group,index)=>{let container=containers[index];if(!container){container=document.createElement('div');container.className='group';container.innerHTML='<div class="group-h"><span class="chev">⌄</span><span class="group-title"></span><div class="spacer"></div><span>⋮</span></div>';host.appendChild(container);}container.dataset.groupId=group.id;const title=$('.group-title',container);if(title)title.textContent=group.name;for(const id of group.rows||[]){if(document.querySelector(`#groups .row[data-signal="${CSS.escape(id)}"]`))continue;const signal=model.document.signals.find(item=>item.id===id);if(!signal)continue;const row=document.createElement('div');row.className='row';row.dataset.signal=id;row.dataset.kind=signal.type==='commentRow'?'comment':signal.type;row.innerHTML=`<span class="role ${signal.role==='output'?'out':signal.role==='internal'?'wire':'in'}">${signal.type==='commentRow'?'▣':signal.role==='output'?'o':signal.role==='internal'?'wire':'i'}</span><span class="row-name">${signal.type==='commentRow'?signal.title:signal.display?.name||signal.name}</span><span class="eye"><svg><use href="icons.svg#i-eye"></use></svg></span><span class="more">⋮</span>`;row.addEventListener('click',()=>controller.actions.selectObject(row));container.appendChild(row);}});}
function applyIssue6Layout(model=getProductionModel()){const controller=window.TimingChartProductionController;const groups=$$('#groups .group');const groupById=new Map((model.document.signalGroups||[]).map(group=>[group.id,group]));groups.forEach(group=>{const data=groupById.get(group.dataset.groupId);if(!data)return;group.classList.toggle('collapsed',Boolean(data.collapsed));$$('.row[data-signal]',group).forEach(row=>{const signal=model.document.signals.find(item=>item.id===row.dataset.signal);row.hidden=Boolean(data.collapsed)||(model.view.hiddenSignals||[]).includes(row.dataset.signal);row.style.marginTop=`${Number(signal?.spacingBefore||0)}px`;row.style.marginBottom=`${Number(signal?.spacingAfter||0)}px`;});});const bottom=$('.left-bottom .group-add');if(bottom){bottom.remove();$('.left-bottom').style.display='none';}const host=$('#cycleCanvas');const groupByRow=new Map((model.document.signalGroups||[]).flatMap(group=>(group.rows||[]).map(id=>[id,group])));$$('#cycleCanvas .wave-row').forEach(row=>{const id=row.dataset.signalId||row.dataset.signal||$('.signal-label',row)?.textContent?.trim();const signal=controller?.selectors?.getSignal?.(id);const group=groupByRow.get(id);if(signal){row.style.marginTop=`${Number(signal.spacingBefore||0)+Number(group?.spacingBefore||0)}px`;row.style.marginBottom=`${Number(signal.spacingAfter||0)+Number(group?.spacingAfter||0)}px`;}if(group?.collapsed)row.hidden=true;});if(host)host.dataset.issue6Spacing='composed';}
function renderIssue6Legend(model=getProductionModel()){const controller=window.TimingChartProductionController;let legend=$('#issue6Legend');if(!model.document.legend?.show){legend?.remove();return;}if(!legend){legend=document.createElement('div');legend.id='issue6Legend';legend.tabIndex=0;legend.style.cssText='position:absolute;z-index:8;padding:4px 8px;background:#fff;border:1px solid #b8c5d4;border-radius:3px;cursor:move;font:11px sans-serif;color:#243047;';$('#cycleCanvas')?.appendChild(legend);legend.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const step=event.shiftKey?10:1;const dx=event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0;const dy=event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0;controller.actions.moveLegend(dx,dy);});let drag=null;legend.addEventListener('pointerdown',event=>{drag={x:event.clientX,y:event.clientY};legend.setPointerCapture?.(event.pointerId);});legend.addEventListener('pointerup',event=>{if(!drag)return;const dx=event.clientX-drag.x;const dy=event.clientY-drag.y;drag=null;if(dx||dy)controller.actions.moveLegend(dx,dy);});}const roles=[...new Set((model.document.signals||[]).filter(signal=>signal.type!=='commentRow').map(signal=>signal.role))];legend.textContent='';roles.forEach(role=>{const item=document.createElement('span');item.style.marginRight='10px';item.textContent=`${role==='input'?'[i]':role==='output'?'[o]':'[wire]'} ${role}`;legend.appendChild(item);});legend.style.left=`${18+Number(model.document.legend.position?.x||0)}px`;legend.style.top=`${18+Number(model.document.legend.position?.y||0)}px`;legend.style.display=model.document.legend.orientation==='vertical'?'grid':'block';}
